mapper.select:
select COUNT(*)::bigint
from crm_org o
left join sys_user u on u.user_id = o.user_id
left join sys_dept d on u.dept_id = d.dept_id
where o.org_id = #{entityId}
${params.dataScope}

select COUNT(*)::bigint
from crm_account a
left join sys_user u on u.user_id = a.user_id
left join sys_dept d on u.dept_id = d.dept_id
where a.account_id = #{entityId}
${params.dataScope}

select COUNT(*)::bigint
from crm_contact c
left join sys_user u on u.user_id = c.user_id
left join sys_dept d on u.dept_id = d.dept_id
where c.contact_id = #{entityId}
${params.dataScope}

select COUNT(*)::bigint
from crm_opty o
left join sys_user u on u.user_id = o.user_id
left join sys_dept d on u.dept_id = d.dept_id
where o.opty_id = #{entityId}
${params.dataScope}

select COUNT(*)::bigint
from crm_lead l
left join sys_user u on u.user_id = l.user_id
left join sys_dept d on u.dept_id = d.dept_id
where l.lead_id = #{entityId}
${params.dataScope}

select COUNT(*)::bigint from crm_task t
where t.related_toid = #{orgId}
  and (t.status_detail is null or t.status_detail != 'Completed')

select COUNT(*)::bigint from crm_contract c
inner join crm_account a on a.account_id = c.account_id
where a.org_id = #{orgId}

select COUNT(*)::bigint from crm_task t
where t.related_toid = #{accountId}
  and (t.status_detail is null or t.status_detail != 'Completed')

select COUNT(*)::bigint from crm_task t
where t.related_toid = #{contactId}
  and (t.status_detail is null or t.status_detail != 'Completed')

select COUNT(*)::bigint from crm_task t
where t.related_toid = #{optyId}
  and (t.status_detail is null or t.status_detail != 'Completed')

select p.pulse_type as pulse_type,
       p.message_data as message_data,
       p.create_time as create_time
from crm_pulse p
where p.relate_id = #{entityId}
 and p.relate_type = #{pulseRelateType}
order by p.create_time desc
limit #{pulseLimit}
